using System.Security.Claims;using DadoRetail.Api.Security;using DadoRetail.Application.Security;using DadoRetail.Domain.Inventory;using DadoRetail.Infrastructure.Persistence;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace DadoRetail.Api.Controllers;[ApiController,Route("api/v1/inventories")]public sealed class InventoriesController(DadoRetailDbContext db):ControllerBase{
[HttpGet,HasPermission(Permissions.InventoryCreate)]public async Task<IActionResult>List(CancellationToken ct)=>Ok(await db.Set<InventoryDocument>().AsNoTracking().Include(x=>x.Lines).OrderByDescending(x=>x.CreatedAtUtc).Take(200).Select(x=>new{x.Id,x.Number,x.WarehouseId,x.Status,x.ApprovedAtUtc,Lines=x.Lines.Count,Difference=x.Lines.Sum(l=>l.ActualQuantity-l.BookQuantity)}).ToListAsync(ct));
[HttpPost,HasPermission(Permissions.InventoryCreate)]public async Task<IActionResult>Create(CreateInventoryRequest r,CancellationToken ct){var d=new InventoryDocument(r.WarehouseId,r.Number);db.Add(d);await db.SaveChangesAsync(ct);return Ok(new{d.Id,d.Status});}
[HttpPost("{id:guid}/start"),HasPermission(Permissions.InventoryCreate)]public async Task<IActionResult>Start(Guid id,CancellationToken ct){var d=await db.Set<InventoryDocument>().FirstOrDefaultAsync(x=>x.Id==id,ct);if(d is null)return NotFound();d.Start();await db.SaveChangesAsync(ct);return Ok(new{d.Id,d.Status});}
[HttpPost("{id:guid}/count"),HasPermission(Permissions.InventoryCreate)]public async Task<IActionResult>Count(Guid id,CountRequest r,CancellationToken ct){var d=await db.Set<InventoryDocument>().Include(x=>x.Lines).FirstOrDefaultAsync(x=>x.Id==id,ct);if(d is null)return NotFound();var productId=await db.Barcodes.Where(x=>x.Value==r.Barcode).Select(x=>(Guid?)x.ProductId).FirstOrDefaultAsync(ct);if(productId is null)return NotFound(new{message="Товар не найден"});var book=await db.StockBalances.Where(x=>x.WarehouseId==d.WarehouseId&&x.ProductId==productId).Select(x=>x.Quantity).FirstOrDefaultAsync(ct);d.Count(productId.Value,book,r.ActualQuantity);await db.SaveChangesAsync(ct);return Ok(new{productId,book,r.ActualQuantity,difference=r.ActualQuantity-book});}
[HttpPost("{id:guid}/submit"),HasPermission(Permissions.InventoryCreate)]public async Task<IActionResult>Submit(Guid id,CancellationToken ct){var d=await db.Set<InventoryDocument>().Include(x=>x.Lines).FirstOrDefaultAsync(x=>x.Id==id,ct);if(d is null)return NotFound();d.Submit();await db.SaveChangesAsync(ct);return Ok(new{d.Id,d.Status});}
[HttpPost("{id:guid}/approve"),HasPermission(Permissions.InventoryApprove)]public async Task<IActionResult>Approve(Guid id,CancellationToken ct){if(!Guid.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier)??User.FindFirstValue("sub"),out var userId))return Unauthorized();await using var tx=await db.Database.BeginTransactionAsync(ct);var d=await db.Set<InventoryDocument>().Include(x=>x.Lines).FirstOrDefaultAsync(x=>x.Id==id,ct);if(d is null)return NotFound();foreach(var l in d.Lines){var b=await db.StockBalances.FirstOrDefaultAsync(x=>x.WarehouseId==d.WarehouseId&&x.ProductId==l.ProductId,ct);if(b is null){b=new StockBalance(d.WarehouseId,l.ProductId);db.StockBalances.Add(b);}var delta=l.ActualQuantity-b.Quantity;if(delta!=0){b.Apply(delta);db.StockMovements.Add(new StockMovement(d.WarehouseId,l.ProductId,delta,StockMovementType.Adjustment,d.Id));}}d.Approve(userId);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Ok(new{d.Id,d.Status,d.ApprovedAtUtc});}}
public sealed record CreateInventoryRequest(Guid WarehouseId,string Number);public sealed record CountRequest(string Barcode,decimal ActualQuantity);
